public class DrinkPreparationsTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String part(String joined, int index) {
        String[] pieces = joined.split(" \\| ", -1);
        return index < pieces.length ? pieces[index] : "(missing piece " + index + ")";
    }

    public static void main(String[] args) {
        Beverage tea = new DrinkPreparations.Tea();
        Beverage coffee = new DrinkPreparations.Coffee();

        check("tea recipe", "boil water; steep the tea; pour into cup", tea.prepare());
        check("coffee recipe",
              "boil water; drip the coffee; pour into cup; add sugar and milk",
              coffee.prepare());
        check("tea adds no extras", false, tea.prepare().contains("add "));
        check("both drinks boil water first", true, coffee.prepare().startsWith("boil water; "));

        Beverage[] order = {tea, coffee, new DrinkPreparations.Tea()};
        String all = DrinkPreparations.prepareAll(order);
        check("prepareAll separator count", 2, all.split(" \\| ", -1).length - 1);
        check("prepareAll first drink", "boil water; steep the tea; pour into cup", part(all, 0));
        check("prepareAll second drink",
              "boil water; drip the coffee; pour into cup; add sugar and milk", part(all, 1));
        check("prepareAll with no drinks", "", DrinkPreparations.prepareAll(new Beverage[0]));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

