    protected String addExtras() {
        return "";
    }
}

public class DrinkPreparations {

    public static class Tea extends Beverage {
        @Override
        protected String brew() {
            return "steep the tea";
        }
    }

    public static class Coffee extends Beverage {
        @Override
        protected String brew() {
            return "drip the coffee";
        }

        @Override
        protected String addExtras() {
            return "add sugar and milk";
        }
    }

    public static String prepareAll(Beverage[] drinks) {
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < drinks.length; i++) {
            if (i > 0) {
                out.append(" | ");
            }
            out.append(drinks[i].prepare());
        }
        return out.toString();
    }
}
